CREATE OR REPLACE FUNCTION public.rsc_admit_loss_correction_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' OR current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 loss admission requires read committed insert' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 inventory ledger required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[NEW.actor_user_id]::text[]);
    RETURN NEW;
END;
$function$

