CREATE OR REPLACE FUNCTION public.rsc_check_loss_chain_events_0159(checked_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; item record; fact jsonb; body jsonb; common jsonb;
    aggregate text; kind text; from_state text; to_state text; key text; reference text; suffix text;
    at timestamptz; identifier uuid; actual jsonb; audit_ids uuid[]; requests jsonb; audit_version bigint;
    inventory_body jsonb; state_body jsonb; outbox_body jsonb; posting_count integer:=0;
BEGIN
    requests:=public.rsc_check_loss_chain_requests_0159(checked_root);
    audit_ids:=public.rsc_loss_inventory_audit_members_0159();
    SELECT version INTO audit_version FROM public.audit_chain_heads WHERE stream_key='inventory';
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    FOR item IN
        SELECT 'inverse' AS category,to_jsonb(r) AS fact FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT 'approval',to_jsonb(d) FROM public.stock_loss_correction_decisions d WHERE root_disposition_id=root.id
        UNION ALL SELECT 'correction',to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;identifier:=(fact->>'id')::uuid;at:=(fact->>'created_at')::timestamptz;
        common:=jsonb_build_object('root_disposition_id',root.id::text,'operation_id',parent.id::text,
            'line_id',root.line_id::text,'original_headquarters_decision_id',root.headquarters_decision_id::text,
            'requester_person_id',parent.requester_id::text,'actor_user_id',fact->>'actor_user_id',
            'actor_person_id',fact->>'actor_person_id','authorization_version',(fact->>'authorization_version')::bigint,
            'reason',fact->>'reason','request_id',fact->>'request_id','request_hash',fact->>'request_hash');
        IF item.category='approval' THEN
            aggregate:='stock_loss_correction_decision';kind:='stock_loss.correction_approved';
            from_state:='awaiting_headquarters';to_state:='approved';
            body:=common||jsonb_build_object('correction_decision_id',identifier::text,'reversal_id',fact->>'reversal_id',
                'expected_reversal_hash',fact->>'expected_reversal_hash','disposition',fact->>'disposition',
                'approval_stage','approved','stock_effect','none');
            IF EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=fact->>'idempotency_key_hash'
                OR (source_document_type=aggregate AND source_document_id=identifier::text)) THEN
                RAISE EXCEPTION '0159 approval cannot post inventory' USING ERRCODE='23514'; END IF;
        ELSE
            common:=common||jsonb_build_object('posting_transaction_id',fact->>'posting_transaction_id',
                'posting_movement_id',fact->>'posting_movement_id','source_account_id',fact->'source_account_id',
                'target_account_id',fact->'target_account_id','quantity',to_char((fact->>'quantity')::numeric,'FM999999999999990.000'),
                'plan_hash',fact->>'plan_hash','status','posted');
            from_state:='pending';to_state:='posted';
            IF item.category='inverse' THEN
                aggregate:='stock_loss_disposition_reversal';kind:='stock_loss.disposition_reversed';
                body:=common||jsonb_build_object('reversal_id',identifier::text,
                    'original_execution_id',COALESCE(fact->>'reversed_correction_id',root.id::text),
                    'reversed_correction_id',fact->'reversed_correction_id','original_transaction_id',fact->>'original_transaction_id',
                    'original_movement_id',fact->>'original_movement_id','stock_effect','restores_original_frozen_share');
            ELSE
                aggregate:='stock_loss_correction_execution';kind:='stock_loss.correction_posted';
                body:=common||jsonb_build_object('correction_execution_id',identifier::text,
                    'correction_decision_id',fact->>'correction_decision_id','reversal_id',fact->>'reversal_id',
                    'disposition',fact->>'disposition','return_operation_id',fact->'return_operation_id',
                    'return_fulfillment_required',fact->>'disposition'='return_to_region',
                    'stock_effect',CASE fact->>'disposition' WHEN 'restore_available' THEN 'frozen_to_available'
                        WHEN 'convert_used' THEN 'frozen_to_used' WHEN 'convert_damaged' THEN 'frozen_to_damaged'
                        WHEN 'return_to_region' THEN 'frozen_to_return_pending' WHEN 'scrap' THEN 'removed_from_managed_assets' END);
            END IF;
        END IF;
        key:=kind||':'||identifier::text;
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type=aggregate AND e.aggregate_id=identifier::text AND e.action=kind
                AND e.actor_user_id=fact->>'actor_user_id' AND e.request_id=fact->>'request_id'
                AND e.before_jsonb='{}'::jsonb AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.from_status=from_state AND e.to_status=to_state AND e.actor_id=fact->>'actor_user_id'
                AND e.reason=kind AND e.idempotency_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type=aggregate AND aggregate_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type=aggregate AND e.aggregate_id=identifier::text
                AND e.event_type=kind AND e.idempotency_key=key AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body))
           OR (SELECT count(*) FROM public.notification_events WHERE business_type=aggregate AND business_id=identifier::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.notification_events e WHERE e.business_type=aggregate AND e.business_id=identifier::text
                AND e.event_type=kind AND e.dedup_key=key AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(body)
                AND e.target_manifest_sha256=encode(sha256(convert_to('notification-person-targets.v1'||chr(10)||parent.requester_id::text,'UTF8')),'hex')
                AND (SELECT count(*) FROM public.notification_person_targets WHERE event_id=e.id)=1
                AND EXISTS(SELECT 1 FROM public.notification_person_targets WHERE event_id=e.id AND person_id=parent.requester_id)) THEN
            RAISE EXCEPTION '0159 exact canonical domain event bundle required' USING ERRCODE='23514'; END IF;
    END LOOP;
    FOR item IN
        SELECT false AS inverse,to_jsonb(r) AS fact FROM public.stock_loss_dispositions r WHERE id=root.id
        UNION ALL SELECT true,to_jsonb(r) FROM public.stock_loss_disposition_reversals r WHERE root_disposition_id=root.id
        UNION ALL SELECT false,to_jsonb(c) FROM public.stock_loss_correction_executions c WHERE root_disposition_id=root.id
    LOOP
        fact:=item.fact;SELECT * INTO tx FROM public.inventory_transactions WHERE id=(fact->>'posting_transaction_id')::uuid;
        at:=tx.posted_at;suffix:=CASE WHEN item.inverse THEN 'reversed' ELSE 'posted' END;
        kind:='inventory.transaction.'||suffix;
        IF tx.posted_at IS NULL OR tx.created_at IS DISTINCT FROM tx.posted_at
           OR tx.idempotency_key_hash IS DISTINCT FROM fact->>'idempotency_key_hash'
           OR (fact->>'created_at')::timestamptz>tx.posted_at
           OR NOT EXISTS(SELECT 1 FROM public.inventory_movements WHERE id=(fact->>'posting_movement_id')::uuid AND created_at=at)
           OR EXISTS(SELECT 1 FROM public.inventory_movement_serials WHERE movement_id=(fact->>'posting_movement_id')::uuid
                AND created_at IS DISTINCT FROM at) THEN
            RAISE EXCEPTION '0159 exact posting time and request key required' USING ERRCODE='23514'; END IF;
        reference:='inventory-request-'||encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(fact->>'request_id','UTF8')),'hex');
        inventory_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_count',1,'movement_type',tx.movement_type,
            'posting_key',tx.posting_key,'reversed_transaction_id',tx.reversed_transaction_id::text,'status','posted');
        state_body:=jsonb_build_object('ledger_cursor',tx.ledger_cursor,'movement_type',tx.movement_type,'request_reference',reference);
        outbox_body:=jsonb_build_object('transaction_id',tx.id::text,'transaction_no',tx.transaction_no,'movement_type',tx.movement_type,
            'ledger_cursor',tx.ledger_cursor,'reversed_transaction_id',tx.reversed_transaction_id::text);
        IF (SELECT count(*) FROM public.audit_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.audit_events e WHERE e.id=ANY(audit_ids) AND e.stream_key='inventory'
                AND e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text AND e.action=kind
                AND e.actor_user_id=tx.actor_user_id AND e.request_id=reference
                AND (e.before_jsonb IS NULL OR e.before_jsonb='null'::jsonb) AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.after_jsonb)=public.rsc_canonical_reconciliation_json_0026(inventory_body))
           OR (SELECT count(*) FROM public.state_transition_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.state_transition_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.from_status IS NULL AND e.to_status='posted' AND e.actor_id=tx.actor_user_id AND e.reason='inventory_transaction_'||suffix
                AND e.idempotency_key='inventory-state-'||encode(sha256(convert_to('cloud_oam.inventory.state.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at AND e.occurred_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.metadata_jsonb)=public.rsc_canonical_reconciliation_json_0026(state_body))
           OR (SELECT count(*) FROM public.outbox_events WHERE aggregate_type='inventory_transaction' AND aggregate_id=tx.id::text)<>1
           OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.aggregate_type='inventory_transaction' AND e.aggregate_id=tx.id::text
                AND e.event_type=kind AND e.idempotency_key='inventory-outbox-'||encode(sha256(convert_to('cloud_oam.inventory.outbox.v1','UTF8')||decode('00','hex')||convert_to(tx.id::text,'UTF8')||decode('00','hex')||convert_to(suffix,'UTF8')),'hex')
                AND e.created_at=at
                AND public.rsc_canonical_reconciliation_json_0026(e.payload_jsonb)=public.rsc_canonical_reconciliation_json_0026(outbox_body)) THEN
            RAISE EXCEPTION '0159 exact canonical inventory posting bundle required' USING ERRCODE='23514'; END IF;
        posting_count:=posting_count+1;
    END LOOP;
    IF requests IS DISTINCT FROM public.rsc_check_loss_chain_requests_0159(checked_root)
       OR audit_version IS DISTINCT FROM (SELECT version FROM public.audit_chain_heads WHERE stream_key='inventory') THEN
        RAISE EXCEPTION '0159 changed event proof snapshot' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('root_disposition_id',root.id::text,'candidate_events',jsonb_array_length(requests),
        'posting_events',posting_count,'audit_version',audit_version);
END;
$function$

