DECLARE parent_actor text; requester uuid; owner_id uuid; required_action text;
    seal public.stock_loss_inverse_request_seals%ROWTYPE; other_table text; collision boolean;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0159 invalid admission trigger' USING ERRCODE='23514'; END IF;
    required_action:=CASE TG_TABLE_NAME
        WHEN 'stock_loss_disposition_reversals' THEN 'reverse_loss'
        WHEN 'stock_loss_correction_decisions' THEN 'approve_loss_correction'
        WHEN 'stock_loss_correction_executions' THEN 'correct_loss'
        WHEN 'stock_loss_inverse_request_seals' THEN 'reverse_loss' WHEN 'stock_loss_correction_approval_seals' THEN 'approve_loss_correction' WHEN 'stock_loss_correction_execution_seals' THEN 'correct_loss' END;
    SELECT p.actor_user_id,p.requester_id,l.owner_org_id INTO parent_actor,requester,owner_id
        FROM public.stock_loss_dispositions r JOIN public.stock_operation_orders p ON p.id=r.operation_id
        JOIN public.stock_locations l ON l.id=p.source_location_id
        WHERE r.id=NEW.root_disposition_id AND p.operation_type='loss_report';
    IF required_action IS NULL OR owner_id IS NULL OR requester IS NULL OR parent_actor IS NULL
       OR (required_action='approve_loss_correction' AND
            (NEW.actor_user_id=parent_actor OR NEW.actor_person_id=requester)) THEN
        RAISE EXCEPTION '0159 exact loss context and independent approver required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_loss_correction_authority_0159(NEW.actor_user_id,NEW.authorization_version,
        NEW.actor_person_id,owner_id,required_action);
    IF TG_TABLE_NAME='stock_loss_inverse_request_seals' THEN
        SELECT * INTO seal FROM public.stock_loss_inverse_request_seals WHERE id=NEW.id;
        IF seal.id IS NULL THEN
            RAISE EXCEPTION '0159 retained inverse seal required' USING ERRCODE='23514'; END IF;
        FOREACH other_table IN ARRAY ARRAY['stock_loss_disposition_reversals',
                'stock_loss_correction_decisions','stock_loss_correction_executions'] LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE idempotency_key_hash=ANY($1) '
                'OR (actor_user_id=$2 AND request_id=$3))',other_table)
                INTO collision USING ARRAY[seal.reversal_key_hash,seal.approval_key_hash,seal.correction_key_hash],
                    seal.actor_user_id,seal.request_id;
            IF collision THEN RAISE EXCEPTION '0159 written request cannot be sealed' USING ERRCODE='23514'; END IF;
        END LOOP;
    ELSIF EXISTS(SELECT 1 FROM public.stock_loss_inverse_request_seals s
        WHERE NEW.idempotency_key_hash IN (s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash)
            OR (s.actor_user_id=NEW.actor_user_id AND s.request_id=NEW.request_id)) THEN
        RAISE EXCEPTION '0159 sealed request cannot be written' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;

DECLARE actor text:=fact->>'actor_user_id'; request text:=fact->>'request_id'; reference text;
    identifier text:=fact->>'id'; posting text:=fact->>'posting_transaction_id';
    key text:=fact->>'idempotency_key_hash'; aggregate text; expected_count integer;
    legacy_table text; keyed boolean; collision boolean;
BEGIN
    aggregate:=CASE required_action WHEN 'reverse_loss' THEN 'stock_loss_disposition_reversal'
        WHEN 'approve_loss_correction' THEN 'stock_loss_correction_decision'
        WHEN 'correct_loss' THEN 'stock_loss_correction_execution' END;
    IF aggregate IS NULL OR actor IS NULL OR request IS NULL OR identifier IS NULL OR key IS NULL THEN
        RAISE EXCEPTION '0159 complete request coordinates required' USING ERRCODE='23514'; END IF;
    expected_count:=CASE WHEN required_action='approve_loss_correction' THEN 1 ELSE 2 END;
    reference:='inventory-request-'||encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(request,'UTF8')),'hex');
    FOR legacy_table,keyed IN SELECT * FROM (VALUES ('stock_operation_orders',true),('stock_loss_dispositions',true),('stock_loss_regional_reviews',true),('stock_loss_headquarters_reviews',true),('stock_loss_request_seals',true),('stock_loss_review_request_seals',true),('stock_loss_disposition_request_seals',false),('stock_operation_cancellations',true),('stock_operation_command_seals',false),('stock_operation_outbounds',true),('stock_operation_shipments',false),('stock_operation_receipts',false),('stock_operation_return_inbounds',true),('stock_operation_return_inbound_seals',false)) legacy(name,keyed) LOOP
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE (actor_user_id=$1 AND request_id=$2)'
            ||CASE WHEN keyed THEN ' OR idempotency_key_hash=$3' ELSE '' END||')',legacy_table)
            INTO collision USING actor,request,key;
        IF collision THEN RAISE EXCEPTION '0159 request conflicts with retained stock command' USING ERRCODE='23514'; END IF;
    END LOOP;
    IF (SELECT count(*) FROM public.inventory_transactions WHERE idempotency_key_hash=key)<>expected_count-1
       OR EXISTS(SELECT 1 FROM public.inventory_transactions WHERE idempotency_key_hash=key AND id::text IS DISTINCT FROM posting)
       OR EXISTS(SELECT 1 FROM public.shipments WHERE idempotency_key_hash=key)
       OR EXISTS(SELECT 1 FROM public.receipts WHERE idempotency_key_hash=key) THEN
        RAISE EXCEPTION '0159 exact keyed correction posting required' USING ERRCODE='23514'; END IF;
    IF (SELECT count(*) FROM public.audit_events e WHERE e.actor_user_id=actor
            AND e.stream_key IN ('inventory','material_request') AND e.request_id IN (request,reference))<>expected_count
       OR EXISTS(SELECT 1 FROM public.audit_events e WHERE e.actor_user_id=actor
            AND e.stream_key IN ('inventory','material_request') AND e.request_id IN (request,reference)
            AND NOT ((e.aggregate_type=aggregate AND e.aggregate_id=identifier AND e.request_id=request)
                OR (posting IS NOT NULL AND e.aggregate_type='inventory_transaction' AND e.aggregate_id=posting AND e.request_id=reference))) THEN
        RAISE EXCEPTION '0159 request audit coordinates contain detached evidence' USING ERRCODE='23514'; END IF;
    IF (SELECT count(*) FROM public.state_transition_events WHERE actor_id=actor AND NOT (COALESCE(aggregate_type IN ('authentication_attempt','login_challenge','sms_dispatch','auth_session')
    AND metadata_jsonb->>'operation'='formal_authentication_state_transition'
    AND metadata_jsonb->>'request_id' ~ '^authreq-[a-f0-9]{64}$'
    AND metadata_jsonb->>'request_reference' IS NULL,false))
            AND (metadata_jsonb->>'request_id'=request OR metadata_jsonb->>'request_reference'=reference))<>expected_count
       OR EXISTS(SELECT 1 FROM public.state_transition_events WHERE actor_id=actor AND NOT (COALESCE(aggregate_type IN ('authentication_attempt','login_challenge','sms_dispatch','auth_session')
    AND metadata_jsonb->>'operation'='formal_authentication_state_transition'
    AND metadata_jsonb->>'request_id' ~ '^authreq-[a-f0-9]{64}$'
    AND metadata_jsonb->>'request_reference' IS NULL,false))
            AND (metadata_jsonb->>'request_id'=request OR metadata_jsonb->>'request_reference'=reference)
            AND NOT ((aggregate_type=aggregate AND aggregate_id=identifier)
                OR (posting IS NOT NULL AND aggregate_type='inventory_transaction' AND aggregate_id=posting))) THEN
        RAISE EXCEPTION '0159 request state coordinates contain detached evidence' USING ERRCODE='23514'; END IF;
    IF (SELECT count(*) FROM public.outbox_events WHERE payload_jsonb->>'actor_user_id'=actor AND payload_jsonb->>'request_id'=request)<>1
       OR EXISTS(SELECT 1 FROM public.outbox_events WHERE payload_jsonb->>'actor_user_id'=actor AND payload_jsonb->>'request_id'=request
            AND (aggregate_type IS DISTINCT FROM aggregate OR aggregate_id IS DISTINCT FROM identifier))
       OR (SELECT count(*) FROM public.notification_events WHERE payload_jsonb->>'actor_user_id'=actor AND payload_jsonb->>'request_id'=request)<>1
       OR EXISTS(SELECT 1 FROM public.notification_events WHERE payload_jsonb->>'actor_user_id'=actor AND payload_jsonb->>'request_id'=request
            AND (business_type IS DISTINCT FROM aggregate OR business_id IS DISTINCT FROM identifier)) THEN
        RAISE EXCEPTION '0159 request domain coordinates contain detached evidence' USING ERRCODE='23514'; END IF;
END;

