CREATE OR REPLACE FUNCTION public.rsc_check_loss_current_correction_0159(checked_fact uuid, required_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE fact jsonb; source_table text; root public.stock_loss_dispositions%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; source public.stock_accounts%ROWTYPE;
    target public.stock_accounts%ROWTYPE; location public.stock_locations%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    effective timestamptz; checked_now timestamptz; account_ids uuid[];
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 correction COMMIT requires read committed' USING ERRCODE='23514'; END IF;
    source_table:=CASE required_action WHEN 'reverse_loss' THEN 'stock_loss_disposition_reversals'
        WHEN 'approve_loss_correction' THEN 'stock_loss_correction_decisions'
        WHEN 'correct_loss' THEN 'stock_loss_correction_executions' END;
    IF source_table IS NULL OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0159 exact correction action and fact required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 correction ledger required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=(fact->>'root_disposition_id')::uuid;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    IF fact IS NULL OR root.id IS NULL OR parent.id IS NULL OR parent.operation_type<>'loss_report' THEN
        RAISE EXCEPTION '0159 exact retained correction context required' USING ERRCODE='23514'; END IF;
    SELECT * INTO source FROM public.stock_accounts WHERE id=root.source_account_id;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[fact->>'actor_user_id']::text[]);
    PERFORM public.rsc_assert_loss_correction_authority_0159(fact->>'actor_user_id',(fact->>'authorization_version')::bigint,
        (fact->>'actor_person_id')::uuid,source.owner_org_id,required_action);
    IF required_action='approve_loss_correction' AND
        (fact->>'actor_user_id'=parent.actor_user_id OR fact->>'actor_person_id'=parent.requester_id::text) THEN
        RAISE EXCEPTION '0159 independent correction approval required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_history_graph_0159(root.id);
    PERFORM public.rsc_check_loss_correction_coordinates_0159(fact,required_action);
    PERFORM public.rsc_check_loss_hold_0145(root.source_account_id);
    -- Approval is a stock-neutral independent fact. Inventory admission below
    -- belongs to the writer that actually moves the approved stock.
    IF required_action='approve_loss_correction' THEN RETURN; END IF;
    effective:=(fact->>'created_at')::timestamptz;
    SELECT * INTO source FROM public.stock_accounts WHERE id=(fact->>'source_account_id')::uuid;
    SELECT * INTO target FROM public.stock_accounts WHERE id=(fact->>'target_account_id')::uuid;
    IF source.id IS NULL OR target.id IS NULL OR source.location_id IS DISTINCT FROM target.location_id
       OR source.material_id IS DISTINCT FROM target.material_id OR source.owner_org_id IS DISTINCT FROM target.owner_org_id
       OR source.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR target.custodian_person_id IS DISTINCT FROM parent.requester_id THEN
        RAISE EXCEPTION '0159 exact current correction accounts required' USING ERRCODE='23514'; END IF;
    account_ids:=ARRAY[source.id,target.id];
    SELECT * INTO location FROM public.stock_locations WHERE id=source.location_id FOR UPDATE;
    PERFORM id FROM public.custody_assignments WHERE location_id=location.id ORDER BY id FOR SHARE;
    PERFORM id FROM public.materials WHERE id=source.material_id FOR SHARE;
    PERFORM id FROM public.material_inventory_policies WHERE material_id=source.material_id ORDER BY id FOR SHARE;
    checked_now:=clock_timestamp();
    SELECT * INTO custody FROM public.custody_assignments WHERE id=(fact->>'custody_assignment_id')::uuid;
    IF location.id IS NULL OR location.status<>'active' OR location.location_type<>'personal'
       OR location.owner_org_id IS DISTINCT FROM source.owner_org_id
       OR location.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR custody.id IS NULL OR custody.location_id IS DISTINCT FROM location.id
       OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR custody.valid_from>checked_now OR (custody.valid_to IS NOT NULL AND custody.valid_to<=checked_now)
       OR (SELECT count(*) FROM public.custody_assignments c WHERE c.location_id=location.id
            AND c.valid_from<=checked_now AND (c.valid_to IS NULL OR c.valid_to>checked_now))<>1
       OR NOT EXISTS(SELECT 1 FROM public.materials WHERE id=source.material_id AND status='active') THEN
        RAISE EXCEPTION '0159 current correction custody or material changed' USING ERRCODE='23514'; END IF;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=checked_now AND (effective_to IS NULL OR effective_to>checked_now))<>1
       OR policy.id::text IS DISTINCT FROM fact->'plan_jsonb'->'policy_fingerprint'->0->>1 THEN
        RAISE EXCEPTION '0159 current correction tracking policy changed' USING ERRCODE='23514'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.inventory_opening_establishments e
        JOIN public.stocktake_postings p ON p.id=e.posting_id AND p.task_id=e.task_id AND p.round_id=e.round_id
        WHERE e.owner_org_id=source.owner_org_id AND e.location_id=source.location_id AND e.established_at<=effective
          AND public.rsc_loss_opening_history_complete_0159(e.task_id,p.inventory_transaction_id)) THEN
        RAISE EXCEPTION '0159 complete established opening required' USING ERRCODE='23514'; END IF;
    IF EXISTS(SELECT 1 FROM public.inventory_freezes f JOIN public.stocktake_scopes s ON s.id=f.stocktake_scope_id AND s.task_id=f.task_id
        JOIN public.stock_accounts a ON a.id=ANY(account_ids)
        WHERE f.status IN ('active','released','cancelled') AND f.freeze_mode='hard'
          AND ((f.valid_from<=checked_now AND (f.valid_to IS NULL OR f.valid_to>checked_now))
            OR (f.valid_from<=effective AND (f.valid_to IS NULL OR f.valid_to>effective)))
          AND s.owner_org_id=a.owner_org_id AND s.location_id=a.location_id
          AND (s.scope_mode='location_all' OR (s.scope_mode='filtered'
            AND (s.material_id IS NULL OR s.material_id=a.material_id)
            AND (s.condition_code IS NULL OR s.condition_code=a.condition_code)
            AND (s.availability_bucket IS NULL OR s.availability_bucket=a.availability_bucket)))) THEN
        RAISE EXCEPTION '0159 correction source or target is hard frozen' USING ERRCODE='23514'; END IF;
END;
$function$

