        'restored_frozen_quantity',to_char(inverse.quantity,'FM999999999999990.000'),'return_boundary',NULL,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(inverse.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR inverse.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical inverse plan mismatch' USING ERRCODE='23514'; END IF;
