CREATE OR REPLACE FUNCTION public.rsc_check_loss_request_binding_0159(checked_kind text, checked_fact uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE binding public.stock_loss_request_key_bindings%ROWTYPE; fact jsonb; source_table text;
    keys text[]; other_table text; keyed boolean; collision boolean;
BEGIN
    source_table:=CASE checked_kind WHEN 'inverse' THEN 'stock_loss_disposition_reversals' WHEN 'approval' THEN 'stock_loss_correction_decisions' WHEN 'correction' THEN 'stock_loss_correction_executions' WHEN 'inverse_seal' THEN 'stock_loss_inverse_request_seals' WHEN 'approval_seal' THEN 'stock_loss_correction_approval_seals' WHEN 'correction_seal' THEN 'stock_loss_correction_execution_seals' END;
    SELECT * INTO binding FROM public.stock_loss_request_key_bindings WHERE fact_id=checked_fact AND binding_kind=checked_kind;
    IF source_table IS NULL OR binding.fact_id IS NULL THEN
        RAISE EXCEPTION '0159 exact database-owned request binding required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    keys:=ARRAY[binding.reversal_key_hash,binding.approval_key_hash,binding.correction_key_hash];
    IF fact IS NULL OR (fact->>'root_disposition_id')::uuid IS DISTINCT FROM binding.root_disposition_id
       OR fact->>'actor_user_id' IS DISTINCT FROM binding.actor_user_id
       OR fact->>'request_id' IS DISTINCT FROM binding.request_id
       OR fact->>'request_hash' IS DISTINCT FROM binding.request_hash
       OR (fact->>'created_at')::timestamptz IS DISTINCT FROM binding.created_at
       OR fact->>'idempotency_key_hash' IS DISTINCT FROM (CASE checked_kind
            WHEN 'approval' THEN binding.approval_key_hash WHEN 'approval_seal' THEN binding.approval_key_hash WHEN 'correction' THEN binding.correction_key_hash WHEN 'correction_seal' THEN binding.correction_key_hash
            ELSE binding.reversal_key_hash END)
       OR (checked_kind IN ('inverse_seal','approval_seal','correction_seal') AND (fact->>'reversal_key_hash' IS DISTINCT FROM binding.reversal_key_hash
            OR fact->>'approval_key_hash' IS DISTINCT FROM binding.approval_key_hash
            OR fact->>'correction_key_hash' IS DISTINCT FROM binding.correction_key_hash)) THEN
        RAISE EXCEPTION '0159 request binding differs from exact fact' USING ERRCODE='23514'; END IF;
    FOR other_table,keyed IN SELECT * FROM (VALUES ('stock_operation_orders',true),('stock_loss_dispositions',true),('stock_loss_regional_reviews',true),('stock_loss_headquarters_reviews',true),('stock_loss_request_seals',true),('stock_loss_review_request_seals',true),('stock_loss_disposition_request_seals',false),('stock_operation_cancellations',true),('stock_operation_command_seals',false),('stock_operation_outbounds',true),('stock_operation_shipments',false),('stock_operation_receipts',false),('stock_operation_return_inbounds',true),('stock_operation_return_inbound_seals',false),('stock_loss_disposition_reversals',true),('stock_loss_correction_decisions',true),('stock_loss_correction_executions',true),('stock_loss_inverse_request_seals',true),('stock_loss_correction_approval_seals',true),('stock_loss_correction_execution_seals',true)) requests(name,keyed) LOOP
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE '
            ||CASE WHEN keyed THEN '(idempotency_key_hash=ANY($1) OR (actor_user_id=$2 AND request_id=$3))'
                ELSE '(actor_user_id=$2 AND request_id=$3)' END
