CREATE OR REPLACE FUNCTION public.rsc_fence_loss_inverse_seal_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identifier uuid; actor text; request text; reference text; key text; aggregate text; body jsonb;
BEGIN
    IF TG_TABLE_NAME='stock_loss_inverse_request_seals' THEN identifier:=NEW.id;
    ELSIF TG_TABLE_NAME IN ('stock_operation_orders','stock_loss_dispositions','stock_loss_regional_reviews','stock_loss_headquarters_reviews','stock_loss_request_seals','stock_loss_review_request_seals','stock_operation_cancellations','stock_operation_outbounds','stock_operation_return_inbounds','stock_loss_disposition_reversals','stock_loss_correction_decisions','stock_loss_correction_executions') THEN
        actor:=NEW.actor_user_id; request:=NEW.request_id; key:=NEW.idempotency_key_hash;
    ELSIF TG_TABLE_NAME IN ('stock_loss_disposition_request_seals','stock_operation_command_seals','stock_operation_shipments','stock_operation_receipts','stock_operation_return_inbound_seals') THEN actor:=NEW.actor_user_id; request:=NEW.request_id;
    ELSIF TG_TABLE_NAME IN ('inventory_transactions','shipments','receipts') THEN key:=NEW.idempotency_key_hash;
    ELSE
        IF TG_TABLE_NAME='audit_events' THEN
            aggregate:=NEW.aggregate_type; body:=NEW.after_jsonb; actor:=NEW.actor_user_id;
            IF aggregate<>'stock_loss_inverse_request_seal' AND NEW.stream_key NOT IN ('inventory','material_request') THEN RETURN NULL; END IF;
            IF aggregate='stock_loss_inverse_request_seal' THEN identifier:=NEW.aggregate_id::uuid;
            ELSIF aggregate='inventory_transaction' THEN reference:=NEW.request_id;
            ELSE request:=NEW.request_id; END IF;
        ELSIF TG_TABLE_NAME='outbox_events' THEN aggregate:=NEW.aggregate_type; body:=NEW.payload_jsonb;
            IF aggregate='stock_loss_inverse_request_seal' THEN identifier:=NEW.aggregate_id::uuid; END IF;
        ELSIF TG_TABLE_NAME='state_transition_events' THEN
            aggregate:=NEW.aggregate_type; body:=NEW.metadata_jsonb; actor:=NEW.actor_id;
            IF COALESCE(aggregate IN ('authentication_attempt','login_challenge','sms_dispatch','auth_session')
    AND body->>'operation'='formal_authentication_state_transition'
    AND body->>'request_id' ~ '^authreq-[a-f0-9]{64}$'
    AND body->>'request_reference' IS NULL,false) THEN RETURN NULL; END IF;
            IF aggregate='stock_loss_inverse_request_seal' THEN identifier:=NEW.aggregate_id::uuid; END IF;
        ELSE aggregate:=NEW.business_type; body:=NEW.payload_jsonb;
            IF aggregate='stock_loss_inverse_request_seal' THEN identifier:=NEW.business_id::uuid; END IF;
        END IF;
        actor:=COALESCE(actor,body->>'actor_user_id'); request:=COALESCE(request,body->>'request_id');
        reference:=COALESCE(reference,body->>'request_reference');
    END IF;
    IF identifier IS NULL AND key IS NULL AND (actor IS NULL OR (request IS NULL AND reference IS NULL)) THEN RETURN NULL; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 inverse seal fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 inverse seal ledger required' USING ERRCODE='23514'; END IF;
    IF identifier IS NOT NULL THEN PERFORM public.rsc_check_loss_inverse_seal_0159(identifier); RETURN NULL; END IF;
    IF EXISTS(SELECT 1 FROM public.stock_loss_inverse_request_seals s WHERE
        key IN (s.reversal_key_hash,s.approval_key_hash,s.correction_key_hash)
        OR (actor=s.actor_user_id AND (request=s.request_id OR reference=s.request_reference))) THEN
        RAISE EXCEPTION '0159 permanently sealed inverse request cannot write' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$function$

