CREATE OR REPLACE FUNCTION public.rsc_fence_loss_request_binding_0159()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE kind text; identifier uuid; raw jsonb:=to_jsonb(NEW); actor text; request text; key text; item record;
BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public' THEN
        RAISE EXCEPTION '0159 request binding insert fence only' USING ERRCODE='23514'; END IF;
    kind:=CASE TG_TABLE_NAME WHEN 'stock_loss_disposition_reversals' THEN 'inverse' WHEN 'stock_loss_correction_decisions' THEN 'approval' WHEN 'stock_loss_correction_executions' THEN 'correction' WHEN 'stock_loss_inverse_request_seals' THEN 'inverse_seal' WHEN 'stock_loss_correction_approval_seals' THEN 'approval_seal' WHEN 'stock_loss_correction_execution_seals' THEN 'correction_seal' END;
    IF TG_TABLE_NAME='stock_loss_request_key_bindings' THEN kind:=NEW.binding_kind;identifier:=NEW.fact_id;
    ELSIF kind IS NOT NULL THEN identifier:=NEW.id; END IF;
    IF kind IS NOT NULL THEN
        PERFORM public.rsc_check_loss_request_binding_0159(kind,identifier); RETURN NULL; END IF;
    actor:=raw->>'actor_user_id';request:=raw->>'request_id';key:=raw->>'idempotency_key_hash';
    IF key IS NULL AND (actor IS NULL OR request IS NULL) THEN RETURN NULL; END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION '0159 request alias fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    FOR item IN SELECT binding_kind,fact_id FROM public.stock_loss_request_key_bindings b
        WHERE key IN (b.reversal_key_hash,b.approval_key_hash,b.correction_key_hash)
            OR (actor=b.actor_user_id AND request=b.request_id)
    LOOP PERFORM public.rsc_check_loss_request_binding_0159(item.binding_kind,item.fact_id); END LOOP;
    RETURN NULL;
END;
$function$

