DECLARE identifier uuid; action text; aggregate text; aggregate_id text; kind text;
    notification public.notification_events%ROWTYPE; tx_id uuid; expected_aggregate text;
    actor text; request text; reference text; key text; body jsonb; matching record;
BEGIN
    IF TG_TABLE_SCHEMA<>'public' OR TG_OP<>'INSERT' THEN
        RAISE EXCEPTION '0159 correction insert guard only' USING ERRCODE='23514'; END IF;
    IF TG_TABLE_NAME='stock_loss_disposition_reversals' THEN identifier:=NEW.id; action:='reverse_loss';
    ELSIF TG_TABLE_NAME='stock_loss_correction_decisions' THEN identifier:=NEW.id; action:='approve_loss_correction';
    ELSIF TG_TABLE_NAME='stock_loss_correction_executions' THEN identifier:=NEW.id; action:='correct_loss';
    ELSIF TG_TABLE_NAME='inventory_transactions' THEN tx_id:=NEW.id; key:=NEW.idempotency_key_hash;
    ELSIF TG_TABLE_NAME IN ('shipments','receipts') THEN key:=NEW.idempotency_key_hash;
    ELSIF TG_TABLE_NAME IN ('stock_operation_orders','stock_loss_dispositions','stock_loss_regional_reviews','stock_loss_headquarters_reviews','stock_loss_request_seals','stock_loss_review_request_seals','stock_loss_disposition_request_seals','stock_operation_cancellations','stock_operation_command_seals','stock_operation_outbounds','stock_operation_shipments','stock_operation_receipts','stock_operation_return_inbounds','stock_operation_return_inbound_seals') THEN
        body:=to_jsonb(NEW);actor:=body->>'actor_user_id';request:=body->>'request_id';key:=body->>'idempotency_key_hash';
    ELSIF TG_TABLE_NAME IN ('inventory_movements','inventory_movement_serials') THEN tx_id:=NEW.transaction_id;
    ELSIF TG_TABLE_NAME IN ('notification_events','notification_person_targets') THEN
        IF TG_TABLE_NAME='notification_events' THEN notification:=NEW;
        ELSE SELECT * INTO notification FROM public.notification_events WHERE id=NEW.event_id; END IF;
        aggregate:=notification.business_type; aggregate_id:=notification.business_id; kind:=notification.event_type;
        body:=notification.payload_jsonb;
    ELSE
        aggregate:=NEW.aggregate_type; aggregate_id:=NEW.aggregate_id;
        IF TG_TABLE_NAME='audit_events' THEN
            kind:=NEW.action;body:=NEW.after_jsonb;actor:=NEW.actor_user_id;request:=NEW.request_id;reference:=NEW.request_id;
        ELSIF TG_TABLE_NAME='state_transition_events' THEN
            kind:=NEW.reason;body:=NEW.metadata_jsonb;actor:=NEW.actor_id;
            IF COALESCE(aggregate IN ('authentication_attempt','login_challenge','sms_dispatch','auth_session')
    AND body->>'operation'='formal_authentication_state_transition'
    AND body->>'request_id' ~ '^authreq-[a-f0-9]{64}$'
    AND body->>'request_reference' IS NULL,false) THEN RETURN NULL; END IF;
        ELSE kind:=NEW.event_type;body:=NEW.payload_jsonb; END IF;
    END IF;
    expected_aggregate:=CASE kind WHEN 'stock_loss.disposition_reversed' THEN 'stock_loss_disposition_reversal'
        WHEN 'stock_loss.correction_approved' THEN 'stock_loss_correction_decision'
        WHEN 'stock_loss.correction_posted' THEN 'stock_loss_correction_execution' END;
    IF expected_aggregate IS NOT NULL AND aggregate IS DISTINCT FROM expected_aggregate THEN
        RAISE EXCEPTION '0159 detached correction event type' USING ERRCODE='23514'; END IF;
    IF TG_TABLE_NAME='audit_events' THEN
        IF expected_aggregate IS NULL
            AND aggregate NOT IN ('stock_loss_disposition_reversal','stock_loss_correction_decision','stock_loss_correction_execution')
            AND NEW.stream_key NOT IN ('inventory','material_request') THEN RETURN NULL; END IF;
    END IF;
    IF aggregate IN ('stock_loss_disposition_reversal','stock_loss_correction_decision','stock_loss_correction_execution') THEN
        identifier:=aggregate_id::uuid;
        action:=CASE aggregate WHEN 'stock_loss_disposition_reversal' THEN 'reverse_loss'
            WHEN 'stock_loss_correction_decision' THEN 'approve_loss_correction' ELSE 'correct_loss' END;
    ELSIF aggregate='inventory_transaction' THEN
        SELECT id INTO tx_id FROM public.inventory_transactions WHERE id::text=aggregate_id;
    END IF;
    IF identifier IS NOT NULL THEN
        -- No stream-based bypass: even an inventory fact mislabeled as an
        -- authentication audit must be rejected by its complete event bundle.
        PERFORM public.rsc_check_loss_current_correction_0159(identifier,action);
    ELSIF action IS NOT NULL THEN
        RAISE EXCEPTION '0159 correction event needs exact fact' USING ERRCODE='23514';
    ELSIF tx_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.inventory_transactions WHERE id=tx_id
        AND source_document_type IN ('stock_loss_disposition_reversal','stock_loss_correction_execution'))
        OR EXISTS(SELECT 1 FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx_id)
        OR EXISTS(SELECT 1 FROM public.stock_loss_correction_executions WHERE posting_transaction_id=tx_id)) THEN
        PERFORM public.rsc_check_loss_transaction_0145(tx_id);
    END IF;
    actor:=COALESCE(actor,body->>'actor_user_id');request:=COALESCE(request,body->>'request_id');
    reference:=COALESCE(reference,body->>'request_reference');
    IF key IS NOT NULL OR (actor IS NOT NULL AND (request IS NOT NULL OR reference IS NOT NULL)) THEN
        FOR matching IN SELECT q.id,q.action FROM (
            SELECT id,actor_user_id,request_id,idempotency_key_hash,'reverse_loss'::text AS action FROM public.stock_loss_disposition_reversals
            UNION ALL SELECT id,actor_user_id,request_id,idempotency_key_hash,'approve_loss_correction' FROM public.stock_loss_correction_decisions
            UNION ALL SELECT id,actor_user_id,request_id,idempotency_key_hash,'correct_loss' FROM public.stock_loss_correction_executions) q
            WHERE (key IS NOT NULL AND q.idempotency_key_hash=key) OR (q.actor_user_id=actor AND (q.request_id=request
                OR reference='inventory-request-'||encode(sha256(convert_to('cloud_oam.inventory.request.v1','UTF8')||decode('00','hex')||convert_to(q.request_id,'UTF8')),'hex')))
        LOOP
            PERFORM public.rsc_check_loss_current_correction_0159(matching.id,matching.action);
        END LOOP;
    END IF;
    RETURN NULL;
END;

