DECLARE root public.stock_loss_dispositions%ROWTYPE; line public.stock_operation_lines%ROWTYPE;
    parent public.stock_operation_orders%ROWTYPE; freeze_tx public.inventory_transactions%ROWTYPE;
    decision public.stock_loss_headquarters_decisions%ROWTYPE; source public.stock_accounts%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; move public.inventory_movements%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE;
    correction public.stock_loss_correction_executions%ROWTYPE;
    approval public.stock_loss_correction_decisions%ROWTYPE;
    item record; previous record; original_serials jsonb; actual_serials jsonb;
    before_cursor bigint; cutoff bigint; prior_cursor bigint; root_cursor bigint;
    active_id uuid; pending_id uuid; visible_root uuid; current_id uuid; next_id uuid;
    current_tx uuid; current_move uuid; current_target uuid;
    seen_executions uuid[]:=ARRAY[]::uuid[]; seen_inverses uuid[]:=ARRAY[]::uuid[];
    seen_transactions uuid[]:=ARRAY[]::uuid[]; seen_movements uuid[]:=ARRAY[]::uuid[];
    total_executions bigint; total_inverses bigint; observed_ids jsonb;
BEGIN
    -- All candidate writers lock this same head before writing even approvals.
    -- The shared read lock makes this multi-statement projection consistent.
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 inventory head required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(max(ledger_cursor),0) INTO before_cursor FROM public.inventory_transactions;
    cutoff:=COALESCE(through_cursor,before_cursor);
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=checked_root;
    SELECT * INTO line FROM public.stock_operation_lines WHERE id=root.line_id;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO freeze_tx FROM public.inventory_transactions WHERE id=parent.posting_transaction_id;
    SELECT * INTO decision FROM public.stock_loss_headquarters_decisions WHERE id=root.headquarters_decision_id;
    SELECT * INTO source FROM public.stock_accounts WHERE id=root.source_account_id;
    IF root.id IS NULL OR line.id IS NULL OR parent.id IS NULL OR freeze_tx.id IS NULL OR decision.id IS NULL OR source.id IS NULL
       OR root.id='00000000-0000-0000-0000-000000000000'::uuid
       OR cutoff<freeze_tx.ledger_cursor OR cutoff>before_cursor
       OR parent.operation_type<>'loss_report' OR line.operation_type<>'loss_report'
       OR parent.id<>line.operation_id OR line.id<>decision.line_id OR root.disposition<>decision.disposition
       OR source.id<>line.reserved_account_id OR source.availability_bucket<>'frozen'
       OR root.quantity<>line.quantity OR root.quantity<=0 OR root.quantity<>trunc(root.quantity,3)
       OR freeze_tx.status<>'posted' OR freeze_tx.movement_type<>'freeze' OR freeze_tx.ledger_cursor<1
       OR freeze_tx.source_document_type<>'stock_operation_loss' OR freeze_tx.source_document_id<>parent.id::text
       OR freeze_tx.reversed_transaction_id IS NOT NULL
       OR EXISTS(SELECT 1 FROM public.inventory_transactions WHERE reversed_transaction_id=freeze_tx.id) THEN
        RAISE EXCEPTION '0159 exact original frozen line required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
        INTO original_serials FROM public.stock_operation_serials WHERE line_id=line.id;
    IF (SELECT count(*) FROM public.stock_operation_serials WHERE line_id=line.id)<>
            (SELECT count(DISTINCT serial_id) FROM public.stock_operation_serials WHERE line_id=line.id)
       OR (original_serials<>'[]'::jsonb AND jsonb_array_length(original_serials)<>line.quantity) THEN
        RAISE EXCEPTION '0159 original serial share required' USING ERRCODE='23514'; END IF;
    SELECT jsonb_build_array(
        (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id),
        (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id),
        (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_correction_decisions WHERE root_disposition_id=root.id))
        INTO observed_ids;
    FOR item IN
        SELECT r.id,r.disposition,r.source_account_id,r.target_account_id,r.quantity,
            r.posting_transaction_id,r.posting_movement_id,r.return_operation_id,false AS is_correction,
            r.actor_user_id,r.created_at FROM public.stock_loss_dispositions r WHERE r.id=root.id
        UNION ALL
        SELECT c.id,c.disposition,c.source_account_id,c.target_account_id,c.quantity,
            c.posting_transaction_id,c.posting_movement_id,c.return_operation_id,true,
            c.actor_user_id,c.created_at FROM public.stock_loss_correction_executions c WHERE c.root_disposition_id=root.id
    LOOP
        SELECT * INTO tx FROM public.inventory_transactions WHERE id=item.posting_transaction_id;
        SELECT * INTO move FROM public.inventory_movements WHERE id=item.posting_movement_id;
        IF tx.id IS NULL OR move.id IS NULL OR item.id='00000000-0000-0000-0000-000000000000'::uuid
           OR item.source_account_id<>source.id OR item.quantity<>line.quantity
           OR item.disposition NOT IN ('restore_available','convert_used','convert_damaged','return_to_region','scrap')
           OR (item.disposition='scrap')<>(item.target_account_id IS NULL)
           OR (item.disposition='return_to_region')<>(item.return_operation_id IS NOT NULL)
           OR item.target_account_id=source.id OR tx.status<>'posted' OR tx.reversed_transaction_id IS NOT NULL
           OR tx.ledger_cursor<=freeze_tx.ledger_cursor OR tx.actor_user_id<>item.actor_user_id
           OR tx.effective_at<>item.created_at OR tx.created_at<item.created_at
           OR tx.source_document_type<>(CASE WHEN item.is_correction THEN 'stock_loss_correction_execution'
                WHEN item.disposition='return_to_region' THEN 'stock_operation_return' ELSE 'stock_loss_disposition' END)
           OR tx.source_document_id<>(CASE WHEN NOT item.is_correction AND item.disposition='return_to_region'
                THEN item.return_operation_id::text ELSE item.id::text END)
           OR tx.movement_type<>(CASE item.disposition WHEN 'restore_available' THEN 'unfreeze'
                WHEN 'return_to_region' THEN 'reserve' WHEN 'scrap' THEN 'scrap' ELSE 'status_change' END)
           OR move.transaction_id<>tx.id OR move.line_no<>1 OR move.from_account_id IS DISTINCT FROM source.id
           OR move.to_account_id IS DISTINCT FROM item.target_account_id OR move.quantity<>line.quantity
           OR move.external_boundary_code IS DISTINCT FROM
                (CASE WHEN item.disposition='scrap' THEN 'stock_operation_scrap' ELSE NULL END)
           OR (SELECT count(*) FROM public.inventory_movements WHERE transaction_id=tx.id)<>1
           OR tx.id=ANY(seen_transactions) OR move.id=ANY(seen_movements) THEN
            RAISE EXCEPTION '0159 exact execution edge required' USING ERRCODE='23514'; END IF;
        seen_transactions:=array_append(seen_transactions,tx.id);seen_movements:=array_append(seen_movements,move.id);
        SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
            INTO actual_serials FROM public.inventory_movement_serials WHERE movement_id=move.id;
        IF actual_serials IS DISTINCT FROM original_serials OR EXISTS(SELECT 1 FROM public.inventory_movement_serials
                WHERE movement_id=move.id AND transaction_id<>tx.id) THEN
            RAISE EXCEPTION '0159 exact execution serial edge required' USING ERRCODE='23514'; END IF;
    END LOOP;
    FOR inverse IN SELECT * FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id LOOP
        SELECT * INTO tx FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
        SELECT * INTO move FROM public.inventory_movements WHERE id=inverse.posting_movement_id;
        IF inverse.reversed_correction_id IS NULL THEN
            current_tx:=root.posting_transaction_id;current_move:=root.posting_movement_id;current_target:=root.target_account_id;
        ELSE
            SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=inverse.reversed_correction_id;
            IF correction.id IS NULL OR correction.root_disposition_id<>root.id THEN
                RAISE EXCEPTION '0159 inverse must reference exact same-root execution' USING ERRCODE='23514'; END IF;
            current_tx:=correction.posting_transaction_id;current_move:=correction.posting_movement_id;current_target:=correction.target_account_id;
        END IF;
        SELECT t.ledger_cursor,m.external_boundary_code INTO previous FROM public.inventory_transactions t
            JOIN public.inventory_movements m ON m.transaction_id=t.id WHERE t.id=current_tx AND m.id=current_move;
        IF tx.id IS NULL OR move.id IS NULL OR previous.ledger_cursor IS NULL
           OR inverse.original_transaction_id<>current_tx OR inverse.original_movement_id<>current_move
           OR inverse.source_account_id IS DISTINCT FROM current_target OR inverse.target_account_id<>source.id
           OR inverse.quantity<>line.quantity OR tx.status<>'posted' OR tx.movement_type<>'reversal'
           OR tx.reversed_transaction_id IS DISTINCT FROM current_tx OR tx.ledger_cursor<=previous.ledger_cursor
           OR tx.actor_user_id<>inverse.actor_user_id OR tx.effective_at<>inverse.created_at OR tx.created_at<inverse.created_at
           OR tx.source_document_type<>'stock_loss_disposition_reversal' OR tx.source_document_id<>inverse.id::text
           OR move.transaction_id<>tx.id OR move.line_no<>1 OR move.from_account_id IS DISTINCT FROM current_target
           OR move.to_account_id IS DISTINCT FROM source.id OR move.quantity<>line.quantity
           OR move.external_boundary_code IS DISTINCT FROM previous.external_boundary_code
           OR (SELECT count(*) FROM public.inventory_movements WHERE transaction_id=tx.id)<>1
           OR tx.id=ANY(seen_transactions) OR move.id=ANY(seen_movements) THEN
            RAISE EXCEPTION '0159 exact inverse edge required' USING ERRCODE='23514'; END IF;
        seen_transactions:=array_append(seen_transactions,tx.id);seen_movements:=array_append(seen_movements,move.id);
        SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
            INTO actual_serials FROM public.inventory_movement_serials WHERE movement_id=move.id;
        IF actual_serials IS DISTINCT FROM original_serials OR EXISTS(SELECT 1 FROM public.inventory_movement_serials
                WHERE movement_id=move.id AND transaction_id<>tx.id) THEN
            RAISE EXCEPTION '0159 exact inverse serial edge required' USING ERRCODE='23514'; END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.reversed_transaction_id=ANY(seen_transactions)
        AND NOT EXISTS(SELECT 1 FROM public.stock_loss_disposition_reversals r WHERE r.root_disposition_id=root.id
            AND r.posting_transaction_id=t.id AND r.original_transaction_id=t.reversed_transaction_id)) THEN
        RAISE EXCEPTION '0159 unrepresented or reversed inverse transaction' USING ERRCODE='23514'; END IF;
    FOR approval IN SELECT * FROM public.stock_loss_correction_decisions WHERE root_disposition_id=root.id LOOP
        SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=approval.reversal_id;
        IF inverse.id IS NULL OR inverse.root_disposition_id<>root.id
           OR approval.expected_reversal_hash<>inverse.request_hash OR approval.created_at<inverse.created_at
           OR approval.id=root.headquarters_decision_id
           OR approval.actor_user_id=parent.actor_user_id OR approval.actor_person_id=parent.requester_id
           OR approval.disposition NOT IN ('restore_available','convert_used','convert_damaged','return_to_region','scrap') THEN
            RAISE EXCEPTION '0159 exact independent correction decision required' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT count(*)+1 INTO total_executions FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id;
    SELECT count(*) INTO total_inverses FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id;
    SELECT ledger_cursor INTO root_cursor FROM public.inventory_transactions WHERE id=root.posting_transaction_id;
    current_id:=root.id;current_tx:=root.posting_transaction_id;prior_cursor:=root_cursor;
    visible_root:=CASE WHEN root_cursor<=cutoff THEN root.id ELSE NULL END;
    LOOP
        IF current_id=ANY(seen_executions) THEN RAISE EXCEPTION '0159 cyclic correction graph' USING ERRCODE='23514'; END IF;
        seen_executions:=array_append(seen_executions,current_id);
        IF prior_cursor<=cutoff THEN active_id:=current_id;pending_id:=NULL; END IF;
        SELECT * INTO inverse FROM public.stock_loss_disposition_reversals
            WHERE root_disposition_id=root.id AND original_transaction_id=current_tx;
        EXIT WHEN inverse.id IS NULL;
        IF (SELECT count(*) FROM public.stock_loss_disposition_reversals
                WHERE root_disposition_id=root.id AND original_transaction_id=current_tx)<>1
           OR inverse.id=ANY(seen_inverses) THEN
            RAISE EXCEPTION '0159 forked inverse graph' USING ERRCODE='23514'; END IF;
        seen_inverses:=array_append(seen_inverses,inverse.id);
        SELECT ledger_cursor INTO prior_cursor FROM public.inventory_transactions WHERE id=inverse.posting_transaction_id;
        IF prior_cursor<=cutoff THEN active_id:=NULL;pending_id:=inverse.id; END IF;
        SELECT * INTO correction FROM public.stock_loss_correction_executions
            WHERE root_disposition_id=root.id AND reversal_id=inverse.id;
        EXIT WHEN correction.id IS NULL;
        SELECT * INTO approval FROM public.stock_loss_correction_decisions WHERE id=correction.correction_decision_id;
        SELECT * INTO tx FROM public.inventory_transactions WHERE id=correction.posting_transaction_id;
        IF (SELECT count(*) FROM public.stock_loss_correction_executions
                WHERE root_disposition_id=root.id AND reversal_id=inverse.id)<>1
           OR approval.id IS NULL OR approval.root_disposition_id<>root.id OR approval.reversal_id<>inverse.id
           OR correction.disposition<>approval.disposition OR correction.created_at<approval.created_at
           OR tx.ledger_cursor<=prior_cursor THEN
            RAISE EXCEPTION '0159 exact authorized successor graph required' USING ERRCODE='23514'; END IF;
        current_id:=correction.id;current_tx:=tx.id;prior_cursor:=tx.ledger_cursor;
    END LOOP;
    IF cardinality(seen_executions)<>total_executions OR cardinality(seen_inverses)<>total_inverses
       OR before_cursor<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions)
       OR observed_ids IS DISTINCT FROM jsonb_build_array(
            (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id),
            (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id),
            (SELECT COALESCE(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM public.stock_loss_correction_decisions WHERE root_disposition_id=root.id)) THEN
        RAISE EXCEPTION '0159 incomplete or changing correction graph' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('line_id',line.id::text,'operation_id',parent.id::text,'freeze_cursor',freeze_tx.ledger_cursor,
        'original_quantity',to_char(line.quantity,'FM999999999999990.000'),'original_serial_ids',original_serials,
        'root_disposition_id',visible_root::text,'active_execution_id',active_id::text,'pending_reversal_id',pending_id::text,
        'frozen_quantity',to_char(CASE WHEN active_id IS NULL THEN line.quantity ELSE 0 END,'FM999999999999990.000'),
        'frozen_serial_ids',CASE WHEN active_id IS NULL THEN original_serials ELSE '[]'::jsonb END);
END;

