CREATE OR REPLACE FUNCTION public.rsc_loss_hold_projection_0159(checked_account uuid, through_cursor bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE account public.stock_accounts%ROWTYPE; item record; piece jsonb; result_lines jsonb:='[]'::jsonb;
    serial_ids jsonb; held_serial_ids uuid[]:=ARRAY[]::uuid[]; identifier uuid; root_id uuid;
    before_cursor bigint; cutoff bigint; amount numeric; version bigint; needed numeric:=0;
    last_account uuid; boundary text; movement text; observed_lines uuid[]; final_lines uuid[];
BEGIN
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 inventory head required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(max(ledger_cursor),0) INTO before_cursor FROM public.inventory_transactions;
    cutoff:=COALESCE(through_cursor,before_cursor);
    SELECT * INTO account FROM public.stock_accounts WHERE id=checked_account;
    IF account.id IS NULL OR account.availability_bucket<>'frozen' OR cutoff<0 OR cutoff>before_cursor THEN
        RAISE EXCEPTION '0159 frozen account and retained cursor required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(array_agg(l.id ORDER BY l.id),ARRAY[]::uuid[]) INTO observed_lines
        FROM public.stock_operation_lines l JOIN public.stock_operation_orders o ON o.id=l.operation_id
        JOIN public.inventory_transactions t ON t.id=o.posting_transaction_id
        WHERE l.operation_type='loss_report' AND l.reserved_account_id=account.id AND t.ledger_cursor<=cutoff;
    FOR item IN SELECT l.*,o.operation_type AS parent_type,o.posting_transaction_id,
            t.ledger_cursor AS freeze_cursor,t.movement_type,t.source_document_type,t.source_document_id,
            t.status AS posting_status,t.reversed_transaction_id
        FROM public.stock_operation_lines l JOIN public.stock_operation_orders o ON o.id=l.operation_id
        JOIN public.inventory_transactions t ON t.id=o.posting_transaction_id
        WHERE l.id=ANY(observed_lines) ORDER BY l.id
    LOOP
        IF item.parent_type<>'loss_report' OR item.movement_type<>'freeze' OR item.posting_status<>'posted'
           OR item.source_document_type<>'stock_operation_loss' OR item.source_document_id<>item.operation_id::text
           OR item.quantity<=0 OR item.material_id<>account.material_id OR item.reversed_transaction_id IS NOT NULL
           OR EXISTS(SELECT 1 FROM public.inventory_transactions WHERE reversed_transaction_id=item.posting_transaction_id) THEN
            RAISE EXCEPTION '0159 exact retained loss freeze required' USING ERRCODE='23514'; END IF;
        SELECT id INTO root_id FROM public.stock_loss_dispositions WHERE line_id=item.id;
        IF root_id IS NULL THEN
            SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb)
                INTO serial_ids FROM public.stock_operation_serials WHERE line_id=item.id;
            piece:=jsonb_build_object('line_id',item.id::text,'operation_id',item.operation_id::text,
                'freeze_cursor',item.freeze_cursor,'original_quantity',to_char(item.quantity,'FM999999999999990.000'),
                'original_serial_ids',serial_ids,'root_disposition_id',NULL,'active_execution_id',NULL,
                'pending_reversal_id',NULL,'frozen_quantity',to_char(item.quantity,'FM999999999999990.000'),
                'frozen_serial_ids',serial_ids);
        ELSE
            IF (SELECT count(*) FROM public.stock_loss_dispositions WHERE line_id=item.id)<>1 THEN
                RAISE EXCEPTION '0159 unique original disposition required' USING ERRCODE='23514'; END IF;
            piece:=public.rsc_loss_chain_projection_0159(root_id,cutoff);
        END IF;
        result_lines:=result_lines||jsonb_build_array(piece);
        needed:=needed+(piece->>'frozen_quantity')::numeric;
        FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(piece->'frozen_serial_ids') LOOP
            IF identifier=ANY(held_serial_ids) THEN
                RAISE EXCEPTION '0159 serial held by multiple loss lines' USING ERRCODE='23514'; END IF;
            held_serial_ids:=array_append(held_serial_ids,identifier);
        END LOOP;
    END LOOP;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=account.id THEN m.quantity ELSE -m.quantity END),0),
            count(DISTINCT t.id) INTO amount,version
        FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND account.id IN (m.from_account_id,m.to_account_id);
    IF amount<0 OR amount<needed THEN
        RAISE EXCEPTION '0159 original and restored loss quantities must remain frozen' USING ERRCODE='23514'; END IF;
    FOREACH identifier IN ARRAY held_serial_ids LOOP
        SELECT m.to_account_id,m.external_boundary_code,t.movement_type INTO last_account,boundary,movement
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id
            WHERE s.serial_id=identifier AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF last_account IS DISTINCT FROM account.id OR movement='scrap'
           OR (boundary IS NOT NULL AND NOT (boundary='stock_operation_scrap' AND movement='reversal')) THEN
            RAISE EXCEPTION '0159 original and restored loss serial must remain frozen' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT COALESCE(array_agg(l.id ORDER BY l.id),ARRAY[]::uuid[]) INTO final_lines
        FROM public.stock_operation_lines l JOIN public.stock_operation_orders o ON o.id=l.operation_id
        JOIN public.inventory_transactions t ON t.id=o.posting_transaction_id
        WHERE l.operation_type='loss_report' AND l.reserved_account_id=account.id AND t.ledger_cursor<=cutoff;
    IF final_lines IS DISTINCT FROM observed_lines OR before_cursor<>
            (SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 loss holds changed during projection' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('schema_version','2.0','source_account_id',account.id::text,'ledger_cursor',cutoff,
        'balance_quantity',to_char(amount,'FM999999999999990.000'),'balance_version',version,'lines',result_lines);
END;
