CREATE OR REPLACE FUNCTION public.rsc_loss_inventory_audit_members_0159()
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE head public.audit_chain_heads%ROWTYPE; event public.audit_events%ROWTYPE;
    expected text; position bigint; document jsonb; visited uuid[]:=ARRAY[]::uuid[];
BEGIN
    SELECT * INTO head FROM public.audit_chain_heads WHERE stream_key='inventory' FOR SHARE;
    IF head.id IS NULL OR head.version IS NULL OR head.version<1 OR head.last_event_id IS NULL
       OR head.last_hash IS NULL OR head.last_hash !~ '^[a-f0-9]{64}$'
       OR head.version<>(SELECT count(*) FROM public.audit_events WHERE stream_key='inventory') THEN
        RAISE EXCEPTION '0159 complete inventory audit head required' USING ERRCODE='23514'; END IF;
    expected:=head.last_hash;position:=head.version;
    WHILE position>0 LOOP
        IF (SELECT count(*) FROM public.audit_events WHERE event_hash=expected)<>1 THEN
            RAISE EXCEPTION '0159 unique inventory audit hash required' USING ERRCODE='23514'; END IF;
        SELECT * INTO event FROM public.audit_events WHERE event_hash=expected;
        IF event.id=ANY(visited) OR event.stream_key IS DISTINCT FROM 'inventory'
           OR event.stream_version IS DISTINCT FROM position OR event.occurred_at IS NULL
           OR (position=head.version AND event.id IS DISTINCT FROM head.last_event_id) THEN
            RAISE EXCEPTION '0159 connected inventory audit chain required' USING ERRCODE='23514'; END IF;
        document:=jsonb_build_object('action',event.action,'actor_user_id',event.actor_user_id,
            'after_jsonb',event.after_jsonb,'aggregate_id',event.aggregate_id,'aggregate_type',event.aggregate_type,
            'before_jsonb',event.before_jsonb,'event_id',event.id::text,
            'occurred_at',to_char(event.occurred_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'previous_hash',event.previous_hash,'request_id',event.request_id,'stream_key','inventory');
        IF event.event_hash IS DISTINCT FROM encode(sha256(convert_to(
            public.rsc_canonical_reconciliation_json_0026(document),'UTF8')),'hex') THEN
            RAISE EXCEPTION '0159 canonical inventory audit hash mismatch' USING ERRCODE='23514'; END IF;
        visited:=array_append(visited,event.id);expected:=event.previous_hash;position:=position-1;
    END LOOP;
    IF expected IS NOT NULL THEN RAISE EXCEPTION '0159 inventory audit genesis required' USING ERRCODE='23514'; END IF;
    RETURN visited;
END;
