CREATE OR REPLACE FUNCTION public.rsc_register_loss_request_binding_0159(checked_kind text, checked_fact uuid, client_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_table text; fact jsonb; action text; hashes text[]; token text; expected text;
    prior public.stock_loss_request_key_bindings%ROWTYPE;
BEGIN
    IF current_setting('transaction_isolation')<>'read committed' OR client_key IS NULL
       OR client_key !~ '^[A-Za-z0-9._:-]{8,200}$' THEN
        RAISE EXCEPTION '0159 exact client key and read committed required' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '0159 request binding ledger required' USING ERRCODE='23514'; END IF;
    source_table:=CASE checked_kind WHEN 'inverse' THEN 'stock_loss_disposition_reversals' WHEN 'approval' THEN 'stock_loss_correction_decisions' WHEN 'correction' THEN 'stock_loss_correction_executions' WHEN 'inverse_seal' THEN 'stock_loss_inverse_request_seals' WHEN 'approval_seal' THEN 'stock_loss_correction_approval_seals' WHEN 'correction_seal' THEN 'stock_loss_correction_execution_seals' END; action:=CASE checked_kind WHEN 'inverse' THEN 'reverse_loss' WHEN 'approval' THEN 'approve_loss_correction' WHEN 'correction' THEN 'correct_loss' WHEN 'inverse_seal' THEN 'reverse_loss' WHEN 'approval_seal' THEN 'approve_loss_correction' WHEN 'correction_seal' THEN 'correct_loss' END;
    IF source_table IS NULL OR checked_fact IS NULL THEN
        RAISE EXCEPTION '0159 exact typed request fact required' USING ERRCODE='23514'; END IF;
    EXECUTE format('SELECT to_jsonb(f) FROM public.%I f WHERE id=$1',source_table) INTO fact USING checked_fact;
    SELECT array_agg(encode(sha256(convert_to('cloud_oam.inventory.idempotency.v1','UTF8')||decode('00','hex')
        ||convert_to('stock-loss:'||a.name||':'||client_key,'UTF8')),'hex') ORDER BY a.ordinal)
        INTO hashes FROM (VALUES ('reverse_loss',1),('approve_loss_correction',2),('correct_loss',3)) a(name,ordinal);
    token:=encode(sha256(convert_to('cloud_oam.loss.correction.key.v1','UTF8')||decode('00','hex')||convert_to(client_key,'UTF8')),'hex');
    expected:=CASE action WHEN 'approve_loss_correction' THEN hashes[2] WHEN 'correct_loss' THEN hashes[3] ELSE hashes[1] END;
    IF fact IS NULL OR fact->>'idempotency_key_hash' IS DISTINCT FROM expected
       OR (checked_kind IN ('inverse_seal','approval_seal','correction_seal') AND (fact->>'reversal_key_hash' IS DISTINCT FROM hashes[1]
            OR fact->>'approval_key_hash' IS DISTINCT FROM hashes[2] OR fact->>'correction_key_hash' IS DISTINCT FROM hashes[3])) THEN
        RAISE EXCEPTION '0159 client key does not prove stored action hashes' USING ERRCODE='23514'; END IF;
    SELECT * INTO prior FROM public.stock_loss_request_key_bindings WHERE fact_id=checked_fact;
    IF prior.fact_id IS NOT NULL THEN
        IF prior.binding_kind IS DISTINCT FROM checked_kind OR prior.key_token IS DISTINCT FROM token
           OR prior.reversal_key_hash IS DISTINCT FROM hashes[1] OR prior.approval_key_hash IS DISTINCT FROM hashes[2]
           OR prior.correction_key_hash IS DISTINCT FROM hashes[3] THEN
            RAISE EXCEPTION '0159 immutable request binding conflict' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_request_binding_0159(checked_kind,checked_fact);
        RETURN;
    END IF;
    INSERT INTO public.stock_loss_request_key_bindings(fact_id,binding_kind,root_disposition_id,actor_user_id,
        request_id,request_hash,key_token,reversal_key_hash,approval_key_hash,correction_key_hash,
        inverse_id,approval_id,correction_id,seal_id,approval_seal_id,correction_seal_id,created_at)
    VALUES(checked_fact,checked_kind,(fact->>'root_disposition_id')::uuid,fact->>'actor_user_id',fact->>'request_id',
        fact->>'request_hash',token,hashes[1],hashes[2],hashes[3],
        CASE WHEN checked_kind='inverse' THEN checked_fact END,CASE WHEN checked_kind='approval' THEN checked_fact END,
        CASE WHEN checked_kind='correction' THEN checked_fact END,CASE WHEN checked_kind='inverse_seal' THEN checked_fact END,
        CASE WHEN checked_kind='approval_seal' THEN checked_fact END,CASE WHEN checked_kind='correction_seal' THEN checked_fact END,(fact->>'created_at')::timestamptz);
    PERFORM public.rsc_check_loss_request_binding_0159(checked_kind,checked_fact);
    IF checked_kind='inverse_seal' THEN PERFORM public.rsc_check_loss_inverse_seal_0159(checked_fact);
    ELSIF checked_kind='approval_seal' THEN PERFORM public.rsc_check_loss_approval_seal_0161(checked_fact);
    ELSIF checked_kind='correction_seal' THEN PERFORM public.rsc_check_loss_execution_seal_0161(checked_fact);
    ELSE PERFORM public.rsc_check_loss_current_correction_0159(checked_fact,action); END IF;
END;
$function$

