CREATE OR REPLACE FUNCTION public.rsc_check_loss_hold_0145(checked_account uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identifier uuid; projection jsonb; piece jsonb; balance public.stock_balances%ROWTYPE;
    held_serial uuid; latest_cursor bigint;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.stock_operation_lines l JOIN public.stock_operation_orders o ON o.id=l.operation_id
        WHERE o.operation_type='loss_report' AND l.reserved_account_id=checked_account) THEN RETURN; END IF;
    -- Raw arithmetic is not evidence of a valid release. Prove the complete
    -- retained request and approval graph before trusting any restored share.
    FOR identifier IN SELECT id FROM public.stock_loss_dispositions WHERE source_account_id=checked_account ORDER BY id LOOP
        PERFORM public.rsc_check_loss_history_graph_0159(identifier);
