CREATE OR REPLACE FUNCTION public.rsc_check_loss_transaction_0145(checked_tx uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tx public.inventory_transactions%ROWTYPE; identifier uuid; account_id uuid;
BEGIN
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=checked_tx;
    IF tx.source_document_type='stock_operation_loss' THEN
        SELECT id INTO identifier FROM public.stock_operation_orders WHERE posting_transaction_id=tx.id;
        IF identifier IS NULL THEN RAISE EXCEPTION '0145 detached loss transaction' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_submission_0145(identifier);
    END IF;
    IF tx.source_document_type='stock_loss_disposition' OR EXISTS(
        SELECT 1 FROM public.stock_loss_dispositions WHERE posting_transaction_id=tx.id) THEN
        SELECT id INTO identifier FROM public.stock_loss_dispositions WHERE posting_transaction_id=tx.id;
        IF identifier IS NULL THEN RAISE EXCEPTION '0150 detached disposition transaction' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_disposition_0150(identifier,true);
    END IF;
    IF tx.source_document_type='stock_loss_disposition_reversal' OR EXISTS(
        SELECT 1 FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx.id) THEN
        SELECT id INTO identifier FROM public.stock_loss_disposition_reversals WHERE posting_transaction_id=tx.id;
        IF identifier IS NULL OR tx.source_document_type<>'stock_loss_disposition_reversal'
           OR tx.source_document_id IS DISTINCT FROM identifier::text THEN
            RAISE EXCEPTION '0159 detached inverse transaction' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_current_correction_0159(identifier,'reverse_loss');
    ELSIF tx.source_document_type='stock_loss_correction_execution' OR EXISTS(
        SELECT 1 FROM public.stock_loss_correction_executions WHERE posting_transaction_id=tx.id) THEN
        SELECT id INTO identifier FROM public.stock_loss_correction_executions WHERE posting_transaction_id=tx.id;
        IF identifier IS NULL OR tx.source_document_type<>'stock_loss_correction_execution'
           OR tx.source_document_id IS DISTINCT FROM identifier::text THEN
            RAISE EXCEPTION '0159 detached correction transaction' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_check_loss_current_correction_0159(identifier,'correct_loss');
    END IF;
    IF tx.reversed_transaction_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.stock_loss_dispositions
        WHERE posting_transaction_id=tx.reversed_transaction_id) OR EXISTS(SELECT 1 FROM public.stock_loss_correction_executions
        WHERE posting_transaction_id=tx.reversed_transaction_id)) AND NOT EXISTS(
            SELECT 1 FROM public.stock_loss_disposition_reversals r WHERE r.posting_transaction_id=tx.id
                AND r.original_transaction_id=tx.reversed_transaction_id
                AND tx.source_document_type='stock_loss_disposition_reversal' AND tx.source_document_id=r.id::text) THEN
        RAISE EXCEPTION '0159 exact dedicated disposition inverse required' USING ERRCODE='23514'; END IF;
    FOR account_id IN SELECT DISTINCT line.reserved_account_id FROM public.stock_operation_lines line
        JOIN public.inventory_movements move ON line.reserved_account_id IN (move.from_account_id,move.to_account_id)
        WHERE line.operation_type='loss_report' AND move.transaction_id=tx.id ORDER BY line.reserved_account_id LOOP
        PERFORM public.rsc_check_loss_hold_0145(account_id);
    END LOOP;
END;
$function$

